const raw = $input.first().json;
const config = $('⚙️ Configuration client').item.json;

// Erreur API (auth, token, query…)
if (raw.error) {
  const detail = raw.error?.message || raw.error?.details?.[0]?.message || JSON.stringify(raw.error);
  return [{
    json: {
      campagnes: [],
      erreur_api: detail,
      nom_agence: config.nom_agence
    }
  }];
}

const results = raw.results || [];
const campagnes = results.map(r => ({
  campagne: r.campaign?.name ?? 'N/A',
  client: r.customer?.descriptiveName ?? config.nom_agence,
  budget: Math.round((parseInt(r.campaignBudget?.amountMicros ?? '0', 10) / 1_000_000) * 100) / 100,
  depense: Math.round((parseInt(r.metrics?.costMicros ?? '0', 10) / 1_000_000) * 100) / 100,
  compte: String(r.campaign?.id ?? 'N/A')
})).filter(c => c.budget > 0);

return [{ json: { campagnes, erreur_api: null } }];

const config = $('⚙️ Configuration client').item.json;
const seuil = config.seuil_alerte_pct;
const { campagnes, erreur_api } = $input.item.json;

const tz = 'Europe/Paris';
const heure = new Date().toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit', timeZone: tz });
const date = new Date().toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long', timeZone: tz });
const heureActuelle = new Date(new Date().toLocaleString('en-US', { timeZone: tz })).getHours();

if (erreur_api) {
  return [{
    json: {
      alertes: [],
      total: 0,
      heure,
      date,
      seuil,
      erreur_api,
      message_erreur: `⚠️ *Erreur Google Ads API*\n${erreur_api}\n_Vérifiez OAuth2, developer token et customer ID._`
    }
  }];
}

function recommandation(c, h) {
  if (c.pct >= 95) return '🔴 Action : pauser ou réduire les enchères de 20 % immédiatement.';
  const burn = h > 0 ? c.depense / h : c.depense / 12;
  const heuresRestantes = burn > 0 ? c.reste / burn : 99;
  const fin = h + heuresRestantes;
  if (fin <= 22) {
    const hf = Math.floor(fin);
    const mf = Math.round((fin - hf) * 60);
    return `🟠 Budget estimé épuisé vers ${hf}h${String(mf).padStart(2, '0')}. Réduire enchères ou surveiller de près.`;
  }
  return '🟡 Rythme élevé — à surveiller en fin de journée.';
}

const alertes = campagnes
  .map(c => ({
    ...c,
    pct: Math.min(999, Math.round((c.depense / c.budget) * 100)),
    reste: Math.round((c.budget - c.depense) * 100) / 100
  }))
  .map(c => ({ ...c, recommandation: recommandation(c, heureActuelle) }))
  .filter(c => c.pct >= seuil)
  .sort((a, b) => b.pct - a.pct);

return [{ json: { alertes, total: alertes.length, heure, date, seuil, erreur_api: null, message_erreur: null } }];

const data = $input.item.json;
const config = $('⚙️ Configuration client').item.json;

if (data.message_erreur) {
  return [{ json: { message: data.message_erreur, nb_alertes: 0, type: 'erreur' } }];
}

const { alertes, heure, date, seuil } = data;
const agence = config.nom_agence;

// Résumé IA global
const budgetExpose = alertes.reduce((sum, a) => sum + a.reste, 0).toFixed(0);
const prioritaire = alertes[0]; // déjà trié par pct desc
const actionPrioritaire = prioritaire.pct >= 95
  ? `pauser *${prioritaire.campagne}* (${prioritaire.pct}%) immédiatement`
  : `surveiller *${prioritaire.campagne}* (${prioritaire.pct}%) en priorité`;
const resume = `📊 *${alertes.length} campagne(s) à risque* · Budget exposé : *${budgetExpose} €* · Action prioritaire : ${actionPrioritaire}`;

const blocs = alertes.map(a => {
  const niveau = a.pct >= 95 ? '🔴 CRITIQUE' : a.pct >= 85 ? '🟠 ATTENTION' : '🟡 SURVEILLANCE';
  return [
    `*${niveau}* · ${a.campagne}`,
    `Client : ${a.client} · Compte ${a.compte}`,
    `Budget ${a.budget} € · Dépensé *${a.depense} €* (*${a.pct}%*) · Reste ${a.reste} €`,
    `→ ${a.recommandation}`
  ].join('\n');
}).join('\n\n');

const message = [
  '🚨 *ALERTE BUDGET GOOGLE ADS*',
  `📅 ${date} · ${heure} (Paris)`,
  `🏢 ${agence} · Seuil ${seuil}%`,
  '────────────────────',
  resume,
  '────────────────────',
  '',
  blocs,
  '',
  `⚡ *${alertes.length} campagne(s)* au-dessus du seuil`,
  '_Workflow P-MON · données du jour (API Google Ads)_'
].join('\n');

return [{ json: { message, nb_alertes: alertes.length, type: 'alerte' } }];
